            e.preventDefault(); dropZone.classList.remove('active');
            const file = e.dataTransfer.files[0];
            if (!file || !file.name.endsWith('.json')) return log('⚠️ Need .json', 'sys');
            const text = await file.text();
            try { JSON.parse(text); } catch { log('⚠️ Invalid JSON', 'sys'); return; }
            if (ws && ws.readyState === WebSocket.OPEN) { ws.send(text); log(`📦 Sent: ${file.name}`, 'sys'); }
            else log('❌ WebSocket not ready', 'sys');
        };

        // ====== Старт ======
        connect();
